effect.shader:
vec4 u_xlat0;
vec4 u_xlat1;
vec3 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec3 u_xlat7;
float u_xlat19;
void main()
{
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlat1.x = u_xlat0.z * 31.0;
    u_xlat7.xyz = u_xlat0.xyz * vec3(0.0302734375, 0.96875, 31.0) + vec3(0.00048828125, 0.015625, 0.0);
    u_xlat1.x = fract(u_xlat1.x);
    u_xlat19 = (-u_xlat1.x) + u_xlat7.z;
    u_xlat7.xy = vec2(u_xlat19) * vec2(0.03125, 0.0) + u_xlat7.xy;
    u_xlat2.xy = u_xlat7.xy + vec2(0.03125, 0.0);
    u_xlat7.xyz = texture(lut, u_xlat7.xy).xyz;
    u_xlat2.xyz = texture(lut, u_xlat2.xy).xyz;
    u_xlat2.xyz = (-u_xlat7.xyz) + u_xlat2.xyz;
    u_xlat1.xyz = u_xlat1.xxx * u_xlat2.xyz + u_xlat7.xyz;
    u_xlat1.xyz = (-u_xlat0.xyz) + u_xlat1.xyz;
    u_xlat1.w = 0.0;
    u_xlat1 = vec4(_blend) * u_xlat1 + u_xlat0;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat0 = u_xlat0 * u_xlat5;
        u_xlat0 = u_xlat3 * u_xlat4 + u_xlat0;
        u_xlat2.x = u_xlat4.x * u_xlat0.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat0.w;
        fragColor.xyz = u_xlat0.xyz;
    } else {
        fragColor = u_xlat1;
    }
    return;
}
